pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function testFuzz_property(address caller, address newOwner) public {
        vm.prank(caller);
        c = new Owned();
        vm.assume(newOwner != caller);
        vm.prank(caller);
        c.setOwner(newOwner);
        assertTrue(c.owner() == newOwner);
    }
}
